function tokens(cls){
  const out=[]; let i=0, cur='';
  let depth=0;
  for(const ch of cls){
    if(ch==='['){depth++;cur+=ch;continue;}
    if(ch===']'){depth--;cur+=ch;continue;}
    if(/\s/.test(ch) && depth===0){ if(cur){out.push(cur);cur='';} continue; }
    cur+=ch;
  }
  if(cur) out.push(cur);
  return out;
}
