const fs = require('fs');
const compiler = require('vue-template-compiler');
const esbuild = require('esbuild');
const files = ['CumulativePanel','BuyerOverviewPanel','DetailModalA','DetailModalB','DetailModalC']
  .map(n => 'src/views/property/marketMonitor/components/'+n+'.vue');
let ok = true;
for (const f of files) {
  const sfc = compiler.parseComponent(fs.readFileSync(f,'utf8'));
  const c = compiler.compile(sfc.template.content);
  if (c.errors && c.errors.length) { console.log('TPL ERR', f, c.errors); ok=false; }
  try { esbuild.transformSync(sfc.script.content, { loader:'js', format:'esm' }); }
  catch(e){ console.log('JS ERR', f, e.message); ok=false; }
  if ok console.log('OK', f);
}
process.exit(ok?0:1);
'@
